// Using JpaRepository — gives us everything CrudRepository has PLUS more
package com.bank.management.repository;

import com.bank.management.model.Account;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.domain.*;
import java.util.List;

public interface AccountRepository extends JpaRepository<Account, String> {

    // Inherited from CrudRepository:
    //   save(entity), findById(id), findAll(), deleteById(id), count(), existsById(id)

    // Inherited from JpaRepository (EXTRA):
    //   findAll(Sort), findAll(Pageable), flush(), saveAndFlush(entity),
    //   deleteAllInBatch(), getReferenceById(id)

    // Custom derived query:
    Page<Account> findByStatus(String status, Pageable pageable);
    List<Account> findByStatus(String status, Sort sort);
}
