```java
// ─── File: src/main/java/com/bank/management/service/AccountManagementService.java ───
package com.bank.management.service;

import com.bank.management.dto.RepositoryComparison;
import com.bank.management.model.Account;
import com.bank.management.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.domain.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.*;

@Service
@RequiredArgsConstructor
@Slf4j
public class AccountManagementService {

    private final AccountRepository accountRepo;

    // ═══ JpaRepository: findAll returns List (not Iterable!) ═══
    @Transactional(readOnly = true)
    public List<Account> getAllAccounts() {
        List<Account> accounts = accountRepo.findAll();  // List<Account> — ready to use!
        log.info("[JpaRepo] findAll → List<Account> size={}", accounts.size());
        return accounts;
    }

    // ═══ JpaRepository: pagination + sorting ═══
    @Transactional(readOnly = true)
    public Page<Account> getAccountsPaged(int page, int size, String sortField) {
        Pageable pageable = PageRequest.of(page, size, Sort.by(Sort.Direction.DESC, sortField));
        Page<Account> result = accountRepo.findByStatus("ACTIVE", pageable);
        log.info("[JpaRepo] page={}, size={}, total={}", result.getNumber(), result.getSize(), result.getTotalElements());
        return result;
    }

    // ═══ JpaRepository: saveAndFlush — immediate persistence ═══
    @Transactional
    public Account createAndFlush(String id, String name, BigDecimal balance) {
        Account account = new Account(id, name, balance);
        Account saved = accountRepo.saveAndFlush(account);  // INSERT immediately! Not deferred.
        log.info("[JpaRepo] saveAndFlush: {} persisted to DB immediately", saved.getAccountId());
        return saved;
    }

    // ═══ JpaRepository: getReferenceById — lazy proxy (no DB hit) ═══
    @Transactional(readOnly = true)
    public String getReferenceDemo(String id) {
        Account proxy = accountRepo.getReferenceById(id);
        // NO SQL fired yet! proxy is a Hibernate lazy proxy.
        log.info("[JpaRepo] getReferenceById: proxy created, NO DB query yet");
        String name = proxy.getHolderName();  // NOW the SQL fires!
        log.info("[JpaRepo] Accessing holderName triggered SELECT: {}", name);
        return name;
    }

    // ═══ COMPARISON REPORT ═══
    public RepositoryComparison compare() {
        Map<String, List<String>> features = new LinkedHashMap<>();

        features.put("CrudRepository", List.of(
            "save(entity), saveAll(entities)",
            "findById(id) → Optional<T>",
            "findAll() → Iterable<T>  ← NOT List!",
            "count(), existsById(id)",
            "deleteById(id), delete(entity), deleteAll()",
            "NO pagination",
            "NO flush/saveAndFlush",
            "NO batch delete",
            "NO getReferenceById"));

        features.put("JpaRepository (adds)", List.of(
            "findAll() → List<T>  ← direct List!",
            "findAll(Sort), findAll(Pageable) → Page<T>",
            "flush(), saveAndFlush(entity), saveAllAndFlush(entities)",
            "deleteAllInBatch(), deleteAllByIdInBatch(ids)",
            "getReferenceById(id) → lazy proxy",
            "findAll(Example<T>) — Query by Example"));

        return new RepositoryComparison(features,
            "Use JpaRepository for Spring Boot apps. CrudRepository only if you need tech-agnostic code.");
    }
}
```

