package com.bank.management.controller;

import com.bank.management.dto.RepositoryComparison;
import com.bank.management.model.Account;
import com.bank.management.service.AccountManagementService;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.web.bind.annotation.*;
import java.util.List;

@RestController
@RequestMapping("/api/v1/accounts")
@RequiredArgsConstructor
public class AccountController {

    private final AccountManagementService service;

    @GetMapping
    public List<Account> all() { return service.getAllAccounts(); }

    @GetMapping("/paged")
    public Page<Account> paged(
        @RequestParam(defaultValue = "0") int page,
        @RequestParam(defaultValue = "3") int size,
        @RequestParam(defaultValue = "balance") String sort) {
        return service.getAccountsPaged(page, size, sort);
    }

    @GetMapping("/compare")
    public RepositoryComparison compare() { return service.compare(); }
}
