// ─── File: src/test/java/com/bank/management/service/CrudVsJpaRepoTest.java ───
package com.bank.management.service;

import org.junit.jupiter.api.Test;
import org.springframework.data.domain.*;
import static org.assertj.core.api.Assertions.*;

class CrudVsJpaRepoTest {

    @Test
    void jpaRepositoryReturnsListNotIterable() {
        // JpaRepository.findAll() → List<T>
        // CrudRepository.findAll() → Iterable<T>
        // List is more convenient — no StreamSupport conversion needed
        java.util.List<String> list = java.util.List.of("A", "B");
        assertThat(list).isInstanceOf(java.util.List.class);
    }

    @Test
    void pageRequestForPagination() {
        Pageable pageable = PageRequest.of(0, 20, Sort.by("balance").descending());
        assertThat(pageable.getPageSize()).isEqualTo(20);
        assertThat(pageable.getSort().getOrderFor("balance").getDirection())
            .isEqualTo(Sort.Direction.DESC);
    }

    @Test
    void deleteAllVsDeleteAllInBatch() {
        // deleteAll():
        //   SELECT * FROM accounts  → load ALL entities
        //   DELETE FROM accounts WHERE id = 'SAV2001'  × N times
        //   Total: 1 SELECT + N DELETEs (SLOW!)

        // deleteAllInBatch():
        //   DELETE FROM accounts  → ONE SQL statement
        //   Total: 1 DELETE (FAST!)
        //   But: skips @PreRemove callbacks!

        // For 100K records:
        // deleteAll: ~30 minutes (100K loads + 100K deletes)
        // deleteAllInBatch: ~2 seconds (one bulk delete)
        assertThat(true).isTrue();
    }

    @Test
    void getReferenceByIdIsLazyProxy() {
        // getReferenceById(id) returns a LAZY proxy — no DB hit!
        // Useful for: trade.setAccount(accountRepo.getReferenceById(accountId))
        // → sets FK without loading the full Account entity
        // Accessing any field triggers the actual SELECT

        // findById(id) → hits DB immediately → returns Optional<Account>
        // getReferenceById(id) → NO DB hit → returns proxy → lazy load on field access
        assertThat(true).isTrue();
    }

    @Test
    void hierarchyOrder() {
        // Repository (marker)
        //   → CrudRepository (save, find, delete, count)
        //     → ListCrudRepository (returns List not Iterable)
        //       → ListPagingAndSortingRepository (findAll(Sort), findAll(Pageable))
        //         → JpaRepository (flush, batch, reference, QBE)
        assertThat(true).isTrue();
    }
}
